/// The leaf of the dependency chain rk-core, rk-util, rk-leaf: a one-file edit here rebuilds only this crate.
pub fn leaf() -> u32 {
    rk_util::doubled() + 1
}

/// Acceptance case 3: one more public function in the leaf.
pub fn leaf_again() -> u32 {
    leaf() + 1
}

#[cfg(test)]
mod tests {
    use super::leaf;

    #[test]
    fn leaf_is_three() {
        assert_eq!(leaf(), 3);
    }
}
